package com.snowglobe.overlay;
import android.app.Activity;
import android.os.Bundle;
import android.content.*;
import android.net.Uri;
import android.provider.Settings;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.PixelFormat;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;

public class MainActivity extends Activity {
 private WindowManager wm;private static SnowView overlay;private static WindowManager overlayManager;private SharedPreferences prefs;private LinearLayout root;
 private final int NAVY=0xff0b1930, PANEL=0xff172b43, WHITE=0xfff3f8ff, MUTED=0xffaec4d7, GREEN=0xff41d5a0;
 @Override public void onCreate(Bundle b){super.onCreate(b);wm=(WindowManager)getSystemService(WINDOW_SERVICE);prefs=getSharedPreferences("snowglobe",MODE_PRIVATE);getWindow().setStatusBarColor(NAVY);getWindow().setNavigationBarColor(NAVY);getWindow().getDecorView().setSystemUiVisibility(0);getWindow().getDecorView().setOnApplyWindowInsetsListener((view,insets)->{int top=insets.getSystemWindowInsetTop();if(root!=null)root.setPadding(22,Math.max(28,top+12),22,52);return view.onApplyWindowInsets(insets);});render();if(prefs.getBoolean("effectsEnabled",true)&&Settings.canDrawOverlays(this))startOverlay(false);}
 private GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(radius);return d;}
 private TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
 private void addText(LinearLayout parent,String s,int size,int color,boolean bold,int bottom){TextView t=text(s,size,color,bold);t.setPadding(0,0,0,bottom);parent.addView(t);}
 private void preset(LinearLayout parent,String name,int palette,int design,int speed,int size,int density,boolean decorations){TextView b=text(name,16,WHITE,true);b.setGravity(Gravity.CENTER_VERTICAL);b.setPadding(20,0,20,0);b.setBackground(bg(0xff315071,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,52);lp.setMargins(0,4,0,10);parent.addView(b,lp);b.setOnClickListener(v->{prefs.edit().putBoolean("snow",true).putBoolean("lights",true).putInt("palette",palette).putInt("lightDesign",design).putInt("speed",speed).putInt("size",size).putInt("density",density).putBoolean("candy",decorations).putBoolean("gifts",decorations).putBoolean("trees",decorations).putBoolean("snowmen",decorations).putBoolean("bulbs",decorations).putBoolean("stars",decorations).putBoolean("confetti",decorations).apply();refreshOverlay();render();Toast.makeText(this,name+" preset applied",Toast.LENGTH_SHORT).show();});}
 private LinearLayout section(String heading,String subtitle){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(20,22,20,24);card.setBackground(bg(PANEL,28));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,0,0,22);root.addView(card,cp);addText(card,heading,19,WHITE,true,9);if(subtitle!=null)addText(card,subtitle,13,MUTED,false,16);return card;}
 private void toggle(LinearLayout parent,String title,String detail,String key,boolean initial){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,9,0,10);LinearLayout labels=new LinearLayout(this);labels.setOrientation(LinearLayout.VERTICAL);labels.addView(text(title,16,WHITE,true));if(detail!=null)labels.addView(text(detail,12,MUTED,false));row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));Switch sw=new Switch(this);sw.setChecked(prefs.getBoolean(key,initial));row.addView(sw);parent.addView(row);sw.setOnCheckedChangeListener((v,on)->{prefs.edit().putBoolean(key,on).apply();refreshOverlay();});}
 private void slider(LinearLayout parent,String title,String key,int initial){LinearLayout row=new LinearLayout(this);row.setOrientation(LinearLayout.VERTICAL);row.setPadding(0,10,0,8);TextView titleView=text(title+"  •  "+prefs.getInt(key,initial)+"%",15,WHITE,true);row.addView(titleView);SeekBar bar=new SeekBar(this);bar.setMax(100);bar.setProgress(prefs.getInt(key,initial));row.addView(bar);parent.addView(row);bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int progress,boolean fromUser){if(fromUser){prefs.edit().putInt(key,progress).apply();titleView.setText(title+"  •  "+progress+"%");refreshOverlay();}}});}
 private void choice(LinearLayout parent,String title,String key,String[] names,int initial){addText(parent,title,15,WHITE,true,7);Spinner sp=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names);sp.setAdapter(adapter);sp.setBackground(bg(0xffe9f3fb,14));sp.setPadding(10,4,10,4);sp.setSelection(Math.min(names.length-1,prefs.getInt(key,initial)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,50);lp.setMargins(0,0,0,14);parent.addView(sp,lp);sp.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> a){}public void onItemSelected(android.widget.AdapterView<?> a,View v,int pos,long id){prefs.edit().putInt(key,pos).apply();refreshOverlay();}});}
 private void heading(LinearLayout parent,String title,String subtitle){addText(parent,title,28,WHITE,true,5);addText(parent,subtitle,14,MUTED,false,18);}
 private void render(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(22,68,22,52);root.setBackgroundColor(NAVY);scroll.addView(root);
 heading(root,"SnowGlobe  ❄","Your personal Christmas studio");
 LinearLayout actions=section("✨  Your holiday experience","Your existing wallpaper stays exactly as it is. Personalize every detail below.");
 TextView start=text("✦  Start Christmas magic",17,0xff09243a,true);start.setGravity(Gravity.CENTER);start.setBackground(bg(GREEN,18));actions.addView(start,new LinearLayout.LayoutParams(-1,56));start.setOnClickListener(v->{prefs.edit().putBoolean("effectsEnabled",true).apply();startOverlay(true);});
 TextView stop=text("Pause effects",15,WHITE,true);stop.setGravity(Gravity.CENTER);stop.setBackground(bg(0xff315071,18));actions.addView(stop,new LinearLayout.LayoutParams(-1,50));stop.setOnClickListener(v->{prefs.edit().putBoolean("effectsEnabled",false).apply();stopOverlay();Toast.makeText(this,"Effects paused",Toast.LENGTH_SHORT).show();});
 LinearLayout presets=section("✨  Christmas scenes","One tap to transform your whole holiday experience.");preset(presets,"🎄  Classic Christmas",0,0,50,55,55,false);preset(presets,"❄  Winter Wonderland",1,1,35,40,70,false);preset(presets,"🎁  North Pole Party",3,2,65,75,85,true);
 LinearLayout snow=section("❄  Snowfall studio","Tune the snow to fit your perfect winter scene.");toggle(snow,"Falling snow","Enable or hide snowflakes","snow",true);slider(snow,"Snowfall speed","speed",50);slider(snow,"Snowflake size","size",50);slider(snow,"Snowfall density","density",55);choice(snow,"Snowflake design","snowStyle",new String[]{"Soft round snow","Classic six-point crystal","Minimal icy crystal"},1);
 LinearLayout lights=section("🎄  Christmas lights","Bright, festive strands along the top of your screen.");toggle(lights,"Show Christmas lights","Switch the top decorations on or off","lights",true);choice(lights,"Light strand design","lightDesign",new String[]{"Festive garland","Draped Christmas lights","Retro glowing bulbs"},0);choice(lights,"Light color theme","palette",new String[]{"Classic Christmas","Winter wonderland","Warm golden glow","Candy-colored rainbow"},0);slider(lights,"Bulb size","lightSize",55);toggle(lights,"Animated twinkle","Turn off blinking for steady holiday lights","twinkle",true);
 LinearLayout fall=section("🎁  Falling decorations","Mix and match any combination of holiday favorites.");toggle(fall,"Candy canes","Striped Christmas treats","candy",false);toggle(fall,"Wrapped presents","Festive gift boxes","gifts",false);toggle(fall,"Christmas trees","Little decorated evergreens","trees",false);toggle(fall,"Snowmen","Friendly frosty characters","snowmen",false);toggle(fall,"Christmas bulbs","Glowing ornaments","bulbs",false);toggle(fall,"Golden stars","Twinkling stars","stars",false);toggle(fall,"Holiday confetti","A little extra celebration","confetti",false);
 LinearLayout comfort=section("🌙  Comfort & accessibility","Make the magic comfortable for your eyes and your battery.");toggle(comfort,"Gentle motion","Save battery with smoother, lower-frequency effects","gentleMotion",true);
 LinearLayout about=section("Made for your Pixel","SnowGlobe draws visual effects over other apps. It does not record your screen or intercept taps.");addText(about,"For best results, enable Display over other apps. Effects run while the app process remains active. Long-running service support is planned.",12,MUTED,false,0);
 TextView footer=text("SnowGlobe 0.6 • Reliability Preview",12,MUTED,false);footer.setGravity(Gravity.CENTER);root.addView(footer);setContentView(scroll);}
 @Override protected void onResume(){super.onResume();if(overlay!=null)overlay.setVisibility(View.INVISIBLE);}
 @Override protected void onPause(){super.onPause();}
 @Override protected void onStop(){super.onStop();if(overlay!=null&&prefs.getBoolean("effectsEnabled",true))overlay.setVisibility(View.VISIBLE);}
 private void refreshOverlay(){if(overlay!=null)overlay.invalidate();}
 private void startOverlay(boolean inform){if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));Toast.makeText(this,"Allow display over other apps, then return and tap Start",Toast.LENGTH_LONG).show();return;}if(overlay!=null){if(inform)Toast.makeText(this,"Christmas magic is running. Go Home to see it!",Toast.LENGTH_SHORT).show();return;}overlay=new SnowView(getApplicationContext(),prefs);overlayManager=(WindowManager)getApplicationContext().getSystemService(WINDOW_SERVICE);WindowManager.LayoutParams p=new WindowManager.LayoutParams(-1,-1,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.START;try{overlayManager.addView(overlay,p);overlay.setVisibility(View.INVISIBLE);if(inform)Toast.makeText(this,"Magic enabled! Go Home to enjoy it.",Toast.LENGTH_LONG).show();}catch(Exception e){overlay=null;Toast.makeText(this,"Unable to start overlay",Toast.LENGTH_LONG).show();}}
 private void stopOverlay(){if(overlay!=null){try{overlayManager.removeView(overlay);}catch(Exception ignored){}overlay=null;}}
 @Override protected void onDestroy(){super.onDestroy();}
}
